	CROFTON_SINGULAR_FOLD_MULTI_REGULAR_COMPONENT_REGULAR_EVENT_COUNT;
    const size_t regular_stream_event_count =
	SINGULAR_POLE_REGULAR_EVENT_COUNT + independent_regular_event_count;
    const size_t regular_event_count = CROFTON_FOLD_REGULAR_EVENT_COUNT +
	regular_stream_event_count;
