static bool
trace_has_expected_multi_periodic_self_seam_stream_events(
    const struct rt_brep_shot_trace &trace, bool reverse,
    double distance_tolerance)
{
    const double forward_distance[MULTI_PERIODIC_EVENT_COUNT] = {
	-MIXED_PERIODIC_RAY_ORIGIN_X - MIXED_PERIODIC_TORUS_OUTER_X,
	-MIXED_PERIODIC_RAY_ORIGIN_X - MIXED_PERIODIC_TORUS_INNER_X,
	-MIXED_PERIODIC_RAY_ORIGIN_X + MIXED_PERIODIC_TORUS_INNER_X,
	-MIXED_PERIODIC_RAY_ORIGIN_X + MIXED_PERIODIC_TORUS_OUTER_X,
	MULTI_PERIODIC_SECOND_TORUS_CENTER_X -
	MIXED_PERIODIC_RAY_ORIGIN_X - MIXED_PERIODIC_TORUS_OUTER_X,
	MULTI_PERIODIC_SECOND_TORUS_CENTER_X -
	MIXED_PERIODIC_RAY_ORIGIN_X - MIXED_PERIODIC_TORUS_INNER_X,
	MULTI_PERIODIC_SECOND_TORUS_CENTER_X -
	MIXED_PERIODIC_RAY_ORIGIN_X + MIXED_PERIODIC_TORUS_INNER_X,
	MULTI_PERIODIC_SECOND_TORUS_CENTER_X -
	MIXED_PERIODIC_RAY_ORIGIN_X + MIXED_PERIODIC_TORUS_OUTER_X
    };
    const double reverse_distance[MULTI_PERIODIC_EVENT_COUNT] = {
	MULTI_PERIODIC_REVERSE_ORIGIN_X -
	(MULTI_PERIODIC_SECOND_TORUS_CENTER_X +
	 MIXED_PERIODIC_TORUS_OUTER_X),
	MULTI_PERIODIC_REVERSE_ORIGIN_X -
	(MULTI_PERIODIC_SECOND_TORUS_CENTER_X +
	 MIXED_PERIODIC_TORUS_INNER_X),
	MULTI_PERIODIC_REVERSE_ORIGIN_X -
	(MULTI_PERIODIC_SECOND_TORUS_CENTER_X -
	 MIXED_PERIODIC_TORUS_INNER_X),
	MULTI_PERIODIC_REVERSE_ORIGIN_X -
	(MULTI_PERIODIC_SECOND_TORUS_CENTER_X -
	 MIXED_PERIODIC_TORUS_OUTER_X),
	MULTI_PERIODIC_REVERSE_ORIGIN_X - MIXED_PERIODIC_TORUS_OUTER_X,
	MULTI_PERIODIC_REVERSE_ORIGIN_X - MIXED_PERIODIC_TORUS_INNER_X,
	MULTI_PERIODIC_REVERSE_ORIGIN_X + MIXED_PERIODIC_TORUS_INNER_X,
	MULTI_PERIODIC_REVERSE_ORIGIN_X + MIXED_PERIODIC_TORUS_OUTER_X
    };
    const int expected_certificate[MULTI_PERIODIC_EVENT_COUNT] = {
	RT_BREP_TRACE_EVENT_PERIODIC_SELF_SEAM,
	RT_BREP_TRACE_EVENT_PERIODIC_SELF_SEAM,
	RT_BREP_TRACE_EVENT_PERIODIC_SELF_SEAM,
	RT_BREP_TRACE_EVENT_PERIODIC_SELF_SEAM,
	RT_BREP_TRACE_EVENT_PERIODIC_SELF_SEAM,
	RT_BREP_TRACE_EVENT_PERIODIC_SELF_SEAM,
	RT_BREP_TRACE_EVENT_PERIODIC_SELF_SEAM,
	RT_BREP_TRACE_EVENT_PERIODIC_SELF_SEAM
    };
    const int expected_direction[MULTI_PERIODIC_EVENT_COUNT] = {
	RT_BREP_TRACE_ENTERING, RT_BREP_TRACE_LEAVING,
	RT_BREP_TRACE_ENTERING, RT_BREP_TRACE_LEAVING,
	RT_BREP_TRACE_ENTERING, RT_BREP_TRACE_LEAVING,
	RT_BREP_TRACE_ENTERING, RT_BREP_TRACE_LEAVING
    };
    return trace_has_expected_ordered_events(trace,
	reverse ? reverse_distance : forward_distance, expected_certificate,
	expected_direction, MULTI_PERIODIC_EVENT_COUNT, distance_tolerance);
}


static bool
trace_is_prepared_multi_periodic_self_seam_stream_result(
    const struct rt_brep_shot_trace &trace, int hits, bool reverse,
    double distance_tolerance)
{
    return trace.reparameterized_surface_faces == MULTI_PERIODIC_FACE_COUNT &&
	trace.physical_event_periodic_self_seam_attempts ==
	    MULTI_PERIODIC_FACE_COUNT &&
	trace.physical_event_periodic_self_seam_certified ==
	    MULTI_PERIODIC_FACE_COUNT &&
	!trace.physical_event_periodic_self_seam_failures &&
	!trace.physical_event_periodic_self_seam_failure_stage &&
	trace.physical_event_periodic_self_seam_boxes ==
	    trace.stored_surface_boxes &&
	trace.physical_event_periodic_self_seam_roots ==
	    trace.stored_local_roots &&
	trace.physical_event_periodic_self_seam_fold_roots ==
	    trace.stored_surface_fold_roots &&
	!trace.physical_event_regular &&
	trace_is_prepared_segment_result(trace, hits,
	trace_has_expected_multi_periodic_self_seam_stream_events(trace,
	    reverse, distance_tolerance), MULTI_PERIODIC_SEGMENT_COUNT);
}


