	trace_is_prepared_crofton_fold_periodic_regular_component_stream_result(
	    trace, hits, false, event_tolerance);
    if (!forward_valid) {
	std::printf("FAIL: forward Crofton fold-periodic-regular stream\n");
	report_trace(trace);
    }
    point_t reverse_origin;
    VJOIN1(reverse_origin, origin,
	CROFTON_FOLD_PERIODIC_REGULAR_COMPONENT_REVERSE_ORIGIN_DISTANCE,
	direction);
    vect_t reverse_direction;
