static bool
check_crofton_singular_fold_stream_impl(struct rt_i *rtip,
    struct resource *resource, double distance_tolerance, bool multi_singular)
{
    if (!rtip || !resource || !(distance_tolerance > 0.0))
	return false;
    const point_t origin = {8.6785353447626861, -11.148065564213111,
	16.106013114539259};
    const vect_t direction = {0.049479789311713616, 0.77131251246993215,
	-0.63453034486696491};
    const vect_t singular_chart_direction = {
	CROFTON_SINGULAR_FOLD_CHART_HORIZONTAL_COMPONENT,
	CROFTON_SINGULAR_FOLD_CHART_HORIZONTAL_COMPONENT,
	CROFTON_SINGULAR_FOLD_CHART_VERTICAL_COMPONENT};
    point_t sphere_pole;
    VJOIN1(sphere_pole, origin, CROFTON_SINGULAR_FOLD_POLE_DISTANCE,
	direction);
    vect_t first_axis;
    vect_t second_axis;
    vect_t third_axis;
    VSET(first_axis, CROFTON_SINGULAR_FOLD_SPHERE_RADIUS, 0.0, 0.0);
    VSET(second_axis, 0.0, CROFTON_SINGULAR_FOLD_SPHERE_RADIUS, 0.0);
    VSET(third_axis, 0.0, 0.0, CROFTON_SINGULAR_FOLD_SPHERE_RADIUS);
    vect_t rotated_first_axis;
    vect_t rotated_second_axis;
    vect_t rotated_third_axis;
    if (!rotate_vector_between_directions(rotated_first_axis, first_axis,
	singular_chart_direction, direction) ||
	!rotate_vector_between_directions(rotated_second_axis, second_axis,
	singular_chart_direction, direction) ||
	!rotate_vector_between_directions(rotated_third_axis, third_axis,
	singular_chart_direction, direction))
	return false;
    point_t sphere_center;
    VSUB2(sphere_center, sphere_pole, rotated_third_axis);
    point_t second_sphere_center = {0.0, 0.0, 0.0};
    if (multi_singular) {
	point_t second_sphere_pole;
	VJOIN1(second_sphere_pole, origin,
	    CROFTON_MULTI_SINGULAR_FOLD_SECOND_POLE_DISTANCE, direction);
	VSUB2(second_sphere_center, second_sphere_pole, rotated_third_axis);
    }
    const point_t fold_center = {0.0, 0.0, 0.0};
    struct bn_tol tolerance = {};
    tolerance.magic = BN_TOL_MAGIC;
    tolerance.dist = 0.0005;
    tolerance.dist_sq = tolerance.dist * tolerance.dist;
    tolerance.perp = 1.0e-6;
    tolerance.para = 1.0 - tolerance.perp;
    ON_Brep *fold_torus = make_torus_brep(fold_center,
	CROFTON_FOLD_TORUS_MAJOR_RADIUS, CROFTON_FOLD_TORUS_MINOR_RADIUS,
	&tolerance);
    ON_Brep *sphere_brep = make_oriented_ellipsoid_brep(sphere_center,
	rotated_first_axis, rotated_second_axis, rotated_third_axis,
	&tolerance);
    ON_Brep *second_sphere_brep = NULL;
    if (multi_singular) {
	second_sphere_brep = make_oriented_ellipsoid_brep(second_sphere_center,
	    rotated_first_axis, rotated_second_axis, rotated_third_axis,
	    &tolerance);
    }
    ON_Brep *compound_brep = multi_singular ?
	make_compound_brep(fold_torus, sphere_brep, second_sphere_brep) :
	make_compound_brep(fold_torus, sphere_brep);
    delete fold_torus;
    delete sphere_brep;
    delete second_sphere_brep;
    if (!compound_brep || !compound_brep->IsSolid()) {
	delete compound_brep;
	return false;
    }
    struct soltab *solid = prepare_brep_solid(rtip, compound_brep);
    if (!solid) {
	delete compound_brep;
	return false;
    }
    const char *stream_name = multi_singular ? "multi-singular-fold" :
	"singular-fold";
    struct rt_brep_shot_trace trace = {};
    const int hits = shoot_trace(solid, rtip, resource, origin, direction,
	trace);
    const double event_tolerance = 2.0 * tolerance.dist;
    const bool forward_valid = multi_singular ?
	trace_is_prepared_crofton_multi_singular_fold_stream_result(trace, hits,
	    false, event_tolerance) :
	trace_is_prepared_crofton_singular_fold_stream_result(trace, hits, false,
	    event_tolerance);
    if (!forward_valid) {
	std::printf("FAIL: forward Crofton %s stream\n", stream_name);
	report_trace(trace);
    }
    const double reverse_origin_distance = multi_singular ?
	CROFTON_MULTI_SINGULAR_FOLD_REVERSE_ORIGIN_DISTANCE :
	CROFTON_SINGULAR_FOLD_REVERSE_ORIGIN_DISTANCE;
    point_t reverse_origin;
    VJOIN1(reverse_origin, origin, reverse_origin_distance, direction);
    vect_t reverse_direction;
    VREVERSE(reverse_direction, direction);
    struct rt_brep_shot_trace reverse_trace = {};
    const int reverse_hits = shoot_trace(solid, rtip, resource,
	reverse_origin, reverse_direction, reverse_trace);
    const bool reverse_valid = multi_singular ?
	trace_is_prepared_crofton_multi_singular_fold_stream_result(reverse_trace,
	    reverse_hits, true, event_tolerance) :
	trace_is_prepared_crofton_singular_fold_stream_result(reverse_trace,
	    reverse_hits, true, event_tolerance);
    if (!reverse_valid) {
	std::printf("FAIL: reverse Crofton %s stream\n", stream_name);
	report_trace(reverse_trace);
    }
    free_solid(solid);
    return forward_valid && reverse_valid;
}


static bool
check_crofton_singular_fold_stream(struct rt_i *rtip,
    struct resource *resource, double distance_tolerance)
{
    return check_crofton_singular_fold_stream_impl(rtip, resource,
	distance_tolerance, false);
}


static bool
check_crofton_multi_singular_fold_stream(struct rt_i *rtip,
    struct resource *resource, double distance_tolerance)
{
    return check_crofton_singular_fold_stream_impl(rtip, resource,
	distance_tolerance, true);
}


static bool
check_crofton_multi_singular_fold_regular_component_stream(
	struct rt_i *rtip, struct resource *resource, double distance_tolerance)
{
	if (!rtip || !resource || !(distance_tolerance > 0.0))
	    return false;
	const point_t origin = {8.6785353447626861, -11.148065564213111,
	    16.106013114539259};
	const vect_t direction = {0.049479789311713616, 0.77131251246993215,
	    -0.63453034486696491};
	const vect_t singular_chart_direction = {
	    CROFTON_SINGULAR_FOLD_CHART_HORIZONTAL_COMPONENT,
	    CROFTON_SINGULAR_FOLD_CHART_HORIZONTAL_COMPONENT,
	    CROFTON_SINGULAR_FOLD_CHART_VERTICAL_COMPONENT};
	point_t sphere_pole;
	VJOIN1(sphere_pole, origin, CROFTON_SINGULAR_FOLD_POLE_DISTANCE,
	    direction);
	vect_t first_axis;
	vect_t second_axis;
	vect_t third_axis;
	VSET(first_axis, CROFTON_SINGULAR_FOLD_SPHERE_RADIUS, 0.0, 0.0);
	VSET(second_axis, 0.0, CROFTON_SINGULAR_FOLD_SPHERE_RADIUS, 0.0);
	VSET(third_axis, 0.0, 0.0, CROFTON_SINGULAR_FOLD_SPHERE_RADIUS);
	vect_t rotated_first_axis;
	vect_t rotated_second_axis;
	vect_t rotated_third_axis;
	if (!rotate_vector_between_directions(rotated_first_axis, first_axis,
		singular_chart_direction, direction) ||
	    !rotate_vector_between_directions(rotated_second_axis, second_axis,
		singular_chart_direction, direction) ||
	    !rotate_vector_between_directions(rotated_third_axis, third_axis,
		singular_chart_direction, direction))
	    return false;
	point_t sphere_center;
	VSUB2(sphere_center, sphere_pole, rotated_third_axis);
	point_t second_sphere_pole;
	VJOIN1(second_sphere_pole, origin,
	    CROFTON_MULTI_SINGULAR_FOLD_SECOND_POLE_DISTANCE, direction);
	point_t second_sphere_center;
	VSUB2(second_sphere_center, second_sphere_pole, rotated_third_axis);
	const point_t fold_center = {0.0, 0.0, 0.0};
	point_t regular_center;
	VJOIN1(regular_center, origin,
	    CROFTON_MULTI_SINGULAR_FOLD_REGULAR_COMPONENT_CENTER_DISTANCE,
	    direction);
	struct bn_tol tolerance = {};
	tolerance.magic = BN_TOL_MAGIC;
	tolerance.dist = 0.0005;
	tolerance.dist_sq = tolerance.dist * tolerance.dist;
	tolerance.perp = 1.0e-6;
	tolerance.para = 1.0 - tolerance.perp;
	ON_Brep *fold_torus = make_torus_brep(fold_center,
	    CROFTON_FOLD_TORUS_MAJOR_RADIUS, CROFTON_FOLD_TORUS_MINOR_RADIUS,
	    &tolerance);
	ON_Brep *sphere_brep = make_oriented_ellipsoid_brep(sphere_center,
	    rotated_first_axis, rotated_second_axis, rotated_third_axis,
	    &tolerance);
	ON_Brep *second_sphere_brep = make_oriented_ellipsoid_brep(
	    second_sphere_center, rotated_first_axis, rotated_second_axis,
	    rotated_third_axis, &tolerance);
	ON_Brep *regular_brep = make_ellipsoid_brep(regular_center,
	    CROFTON_MULTI_SINGULAR_FOLD_REGULAR_COMPONENT_RADIUS, &tolerance);
	ON_Brep *compound_brep = make_compound_brep(fold_torus, sphere_brep,
	    second_sphere_brep, regular_brep);
	delete fold_torus;
	delete sphere_brep;
	delete second_sphere_brep;
	delete regular_brep;
	if (!compound_brep || !compound_brep->IsSolid()) {
	    delete compound_brep;
	    return false;
	}
	struct soltab *solid = prepare_brep_solid(rtip, compound_brep);
	if (!solid) {
	    delete compound_brep;
	    return false;
	}
	struct rt_brep_shot_trace trace = {};
	const int hits = shoot_trace(solid, rtip, resource, origin, direction,
	    trace);
	const double event_tolerance = 2.0 * tolerance.dist;
	const bool forward_valid =
	    trace_is_prepared_crofton_multi_singular_fold_regular_component_stream_result(
		trace, hits, false, event_tolerance);
	if (!forward_valid) {
	    std::printf("FAIL: forward Crofton multi-singular-fold-regular stream\n");
	    report_trace(trace);
	}
	point_t reverse_origin;
	VJOIN1(reverse_origin, origin,
	    CROFTON_MULTI_SINGULAR_FOLD_REGULAR_COMPONENT_REVERSE_ORIGIN_DISTANCE,
	    direction);
	vect_t reverse_direction;
	VREVERSE(reverse_direction, direction);
	struct rt_brep_shot_trace reverse_trace = {};
	const int reverse_hits = shoot_trace(solid, rtip, resource,
	    reverse_origin, reverse_direction, reverse_trace);
	const bool reverse_valid =
	    trace_is_prepared_crofton_multi_singular_fold_regular_component_stream_result(
		reverse_trace, reverse_hits, true, event_tolerance);
	if (!reverse_valid) {
	    std::printf("FAIL: reverse Crofton multi-singular-fold-regular stream\n");
	    report_trace(reverse_trace);
	}
	free_solid(solid);
	return forward_valid && reverse_valid;
}


