static bool
check_periodic_pole_stream(struct rt_i *rtip, struct resource *resource,
    double distance_tolerance)
{
    if (!rtip || !resource || !(distance_tolerance > 0.0))
	return false;
    const point_t sphere_center = {0.0, 0.0, 0.0};
    const point_t origin = {-8.48528137423857, -8.48528137423857, 26.0};
    const vect_t direction = {0.424264068711929, 0.424264068711929, -0.8};
    const vect_t torus_normal = {MIXED_POLE_ORTHOGONAL_RAY_COMPONENT,
	-MIXED_POLE_ORTHOGONAL_RAY_COMPONENT, 0.0};
    point_t torus_center;
    VJOIN1(torus_center, origin, PERIODIC_POLE_TORUS_CENTER_DISTANCE,
	direction);
    ON_Brep *sphere_brep = make_ellipsoid_brep(sphere_center,
	MIXED_POLE_RADIUS, &rtip->rti_tol);
    ON_Brep *torus_brep = make_oriented_torus_brep(torus_center,
	torus_normal, direction, MIXED_PERIODIC_TORUS_MAJOR_RADIUS,
	MIXED_PERIODIC_TORUS_MINOR_RADIUS, &rtip->rti_tol);
    ON_Brep *compound_brep = make_compound_brep(sphere_brep, torus_brep);
    delete sphere_brep;
    delete torus_brep;
    if (!compound_brep || !compound_brep->IsSolid()) {
	delete compound_brep;
	return false;
    }
    struct soltab *compound_solid = prepare_brep_solid(rtip, compound_brep);
    if (!compound_solid) {
	delete compound_brep;
	return false;
    }
    struct rt_brep_shot_trace trace = {};
    const int hits = shoot_trace(compound_solid, rtip, resource, origin,
	direction, trace);
    const bool forward_valid = trace_is_prepared_periodic_pole_stream_result(
	trace, hits, false, distance_tolerance);
    if (!forward_valid)
	report_trace(trace);
    if (!forward_valid)
	report_surface_spans(compound_brep);
    point_t reverse_origin;
    VJOIN1(reverse_origin, origin, PERIODIC_POLE_REVERSE_ORIGIN_DISTANCE,
	direction);
    vect_t reverse_direction;
    VREVERSE(reverse_direction, direction);
    struct rt_brep_shot_trace reverse_trace = {};
    const int reverse_hits = shoot_trace(compound_solid, rtip, resource,
	reverse_origin, reverse_direction, reverse_trace);
    const bool reverse_valid = trace_is_prepared_periodic_pole_stream_result(
	reverse_trace, reverse_hits, true, distance_tolerance);
    if (!reverse_valid)
	report_trace(reverse_trace);
    if (!reverse_valid)
	report_surface_spans(compound_brep);
    const bool valid = forward_valid && reverse_valid;
    free_solid(compound_solid);
    return valid;
}


