    delete regular_first_brep;
    delete regular_second_brep;
    if (!compound_brep || !compound_brep->IsSolid()) {
        delete compound_brep;
        return false;
    }
    struct soltab *compound_solid = prepare_brep_solid(rtip, compound_brep);
